$ErrorActionPreference='Stop'
. './docs/evidence/consultation-agent-native-20261006/approved-run/approved-http.ps1'
$maint=New-ProductHttp
try {
 $null=Login-ApprovedMember
 $task=Get-Content (Join-Path $out 'new-task.json') -Raw|ConvertFrom-Json;$scope=Get-Content (Join-Path $out 'new-source-task-scope.json') -Raw|ConvertFrom-Json;$source=Get-Content (Join-Path $out 'new-source-enable.json') -Raw|ConvertFrom-Json;$worker=Get-Content (Join-Path $out 'new-worker-registration.json') -Raw|ConvertFrom-Json
 $rebind=Approved-Send $maint POST '/v2/consultation/source-contracts/scopes/PATENTSVIEW_ZENODO_2024/rebind' @{taskId=$task.taskId;memberSubject='7b389c47-9f5b-4004-ad95-084600b351ef';taskVersion=2;sourceRowVersion=$source.sourceEpoch;expiresAt=$cutoff.ToString('o');expectedScopeVersion=$scope.scopeVersion;previousQueryGrantId=$scope.queryGrantId} 'new-source-goal-rebind'
 $view=Approved-Send $http GET "/v2/consultation/tasks/$($task.taskId)/retrieval-workspace" $null 'admitted-workspace'
 $me=Approved-Send $http GET '/v2/identity/me' $null 'admitted-member'
 if($view.task.id -ne $task.taskId -or $view.task.version -ne 2 -or $view.goal.queryObject -ne 'robot vacuum' -or $view.sources.Count -ne 1 -or $view.sources[0].contractVersion -ne 'patentsview-capture-contract-agent-20261006-01' -or $view.sources[0].taskVersion -ne 2 -or $null -ne $view.result){throw 'Current same task/goal/source exact admission mismatch'}
 $cfg=Get-Content (Join-Path $vault 'container-deployment.json') -Raw|ConvertFrom-Json -AsHashtable;$resident=Get-Content (Join-Path $out 'resident-product.json') -Raw|ConvertFrom-Json
 $active=(docker inspect $resident.id|ConvertFrom-Json)[0];if($LASTEXITCODE -ne 0 -or -not $active.State.Running -or $cfg.settings.PRODUCT_CONSULTATION_WORKSPACE_WORKER_SUBJECT -ne $worker.subjectId){throw 'Current formal worker deployment mismatch'}
 $certificate=[Security.Cryptography.X509Certificates.X509Certificate2]::new((Join-Path $vault 'worker-v2026100601.p12'),(Read-ProductSecret 'worker-certificate-v2026100601.credential.xml'));try{if($certificate.NotAfter.ToUniversalTime() -gt $cutoff.UtcDateTime -or $certificate.NotAfter -le (Get-Date)){throw 'Worker certificate outside fixed approved window'}}finally{$certificate.Dispose()}
 [ordered]@{observedAt=[DateTimeOffset]::Now.ToString('o');gate='CON-CURRENT-ADMISSION';humanApprovalId='CON-AGENT-TASK-USER-20261006-01';taskId=$task.taskId;taskVersion=2;goalId=$view.goal.goalId;inputId=$view.goal.inputId;sourceId=$view.sources[0].sourceId;sourceEpoch=$view.sources[0].sourceEpoch;sourceScopeId=$view.sources[0].scopeId;sourceScopeVersion=$view.sources[0].scopeVersion;workerSubject=$worker.subjectId;container=$resident.id;currentFormalMember=$me.subject;fixedLatestExpiry=$cutoff.ToString('o');currentContractAndScope=$true;realProductWorker=$true;modelApprovalUnchanged=$true;noPreviousRetrieval=$true;browserE2e=$false;targetCoverageGap='Approved 40 record titles have no robot/vacuum matches; relevance must not be inferred from nonempty semantic candidates'}|ConvertTo-Json -Depth 15|Set-Content (Join-Path $out 'current-admission.json')
 Write-Output "CURRENT_FORMAL_ADMISSION_VERIFIED task=$($task.taskId) worker=$($worker.subjectId) sourceEpoch=$($view.sources[0].sourceEpoch)"
}finally{Save-ApprovedTrace 'current-admission';$maint.Dispose();$http.Dispose();$password=$null;$approvedToken=$null}
